const items = $input.all();

return items.map((item) => {
  const html = String(item.json.data ?? item.json.body ?? "");

  let text = html
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
    .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;|&#160;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\s+/g, " ")
    .trim();

  // Ana sayfanın esas içeriğinin başladığı nokta
  const start = text.indexOf("Hej! IKEA Türkiye'ye hoş geldiniz");

  if (start !== -1) {
    text = text.slice(start);
  }

  // Altbilgi ve form içeriklerini kes
  const end = text.indexOf("Hakkımızda IKEA Konsepti");

  if (end !== -1) {
    text = text.slice(0, end);
  }

  text = text.trim();

  return {
    json: {
      source: "https://www.ikea.com.tr/",
      title: "IKEA Türkiye - Ana Sayfa",
      text,
      character_count: text.length
    }
  };
});

