return items.map((item) => {
  const html = String(item.json.data ?? item.json.body ?? "");

  let text = html
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
    .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;|&#160;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/\s+/g, " ")
    .trim();

  // Hizmetler sayfasının ana içeriği
  const start = text.indexOf(
    "Montaj, Nakliye ve Ölçüm Hizmetleri"
  );

  if (start !== -1) {
    text = text.slice(start);
  }

  // Altbilgiyi çıkar
  const end = text.indexOf("Hakkımızda IKEA Konsepti");

  if (end !== -1) {
    text = text.slice(0, end);
  }

  text = text.trim();

  return {
    json: {
      source: "https://www.ikea.com.tr/hizmetler",
      title: "IKEA Türkiye - Hizmetler",
      text,
      character_count: text.length
    }
  };
});

const documents = $input.all();

const CHUNK_SIZE = 800;
const OVERLAP = 150;

const output = [];

for (const item of documents) {
  const { source, title, text } = item.json;

  if (!text || !text.trim()) continue;

  let start = 0;
  let index = 0;

  while (start < text.length) {
    let end = Math.min(start + CHUNK_SIZE, text.length);

    // Kelimenin ortasında kesmemeye çalış
    if (end < text.length) {
      const lastSpace = text.lastIndexOf(" ", end);

      if (lastSpace > start + CHUNK_SIZE / 2) {
        end = lastSpace;
      }
    }

    const chunk = text.slice(start, end).trim();

    if (chunk) {
      output.push({
        json: {
          text: chunk,
          source,
          title,
          chunk_index: index,
          chunk_id: `${title}-${index}`,
          chunk_length: chunk.length
        }
      });
    }

    if (end >= text.length) break;

    start = Math.max(start + 1, end - OVERLAP);
    index++;
  }
}

return output;
